import java.util.*;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.net.URI;

/** Gestão de turmas, matérias, matrículas e materiais. Os dados internos não são enviados diretamente ao cliente. */
final class Academico {
    static final int MAX_FILE = 2 * 1024 * 1024, MAX_TOTAL = 16 * 1024 * 1024;
    private final SistemaEscolar s;
    private final List<Map<String,Object>> materias=new ArrayList<>(), turmas=new ArrayList<>(), passes=new ArrayList<>(), materiais=new ArrayList<>();
    Academico(SistemaEscolar s){this.s=s;}
    static void exigir(boolean ok,String msg){if(!ok)throw new IllegalArgumentException(msg);}
    static String texto(String x,int max){x=x.trim();exigir(!x.isEmpty()&&x.length()<=max,"Campo obrigatório ou longo demais.");return x;}
    static int id(Map<String,Object> m,String key){return Json.num(m,key);}
    static String str(Map<String,Object> m,String key){return Json.str(m,key);}
    static int novoId(List<Map<String,Object>> l){return l.stream().mapToInt(x->id(x,"id")).max().orElse(0)+1;}
    static Map<String,Object> achar(List<Map<String,Object>> l,int id){return l.stream().filter(x->id(x,"id")==id).findFirst().orElseThrow(()->new IllegalArgumentException("Registro inexistente."));}
    static List<Object> membros(Map<String,Object> turma){return Json.list(turma.get("membros"));}
    static boolean contem(Map<String,Object> turma,int aluno){return membros(turma).stream().anyMatch(x->((Number)x).intValue()==aluno);}
    private Map<String,Object> materia(int id){return achar(materias,id);}
    private Map<String,Object> turma(int id){return achar(turmas,id);}
    private void professor(Usuario u){exigir(u.isProfessor(),"Apenas professores podem gerenciar turmas e materiais.");}
    private Map<String,Object> minhaTurma(Usuario u,int id){professor(u);Map<String,Object> t=turma(id);exigir(id(t,"professor")==u.getId(),"Turma não pertence a este professor.");return t;}
    boolean podeVer(Usuario u,int id){return id==0||turmas.stream().anyMatch(t->id(t,"id")==id&&(u.isProfessor()?id(t,"professor")==u.getId():contem(t,u.getId())));}
    String nomeTurma(int id){return id==0?"Geral (legado)":str(turma(id),"nome");}
    String materiaDaTurma(Usuario u,int id){return str(materia(id(minhaTurma(u,id),"materia")),"nome");}
    void criarMateria(Usuario u,String nome){professor(u);String n=texto(nome,100);exigir(materias.stream().noneMatch(m->id(m,"professor")==u.getId()&&str(m,"nome").equalsIgnoreCase(n)),"Matéria já cadastrada.");materias.add(Json.obj("id",novoId(materias),"professor",u.getId(),"nome",n));}
    void criarTurma(Usuario u,int mid,String nome){professor(u);Map<String,Object> m=materia(mid);exigir(id(m,"professor")==u.getId(),"Matéria não pertence a este professor.");String n=texto(nome,100);exigir(turmas.stream().noneMatch(t->id(t,"materia")==mid&&str(t,"nome").equalsIgnoreCase(n)),"Turma já cadastrada nesta matéria.");turmas.add(Json.obj("id",novoId(turmas),"professor",u.getId(),"materia",mid,"nome",n,"membros",new ArrayList<>()));}
    void adicionarAluno(Usuario u,int tid,int aid){Map<String,Object> t=minhaTurma(u,tid);Usuario a=s.usuario(aid);exigir(!a.isProfessor(),"Selecione um aluno.");exigir(!contem(t,aid),"Aluno já está nesta turma.");membros(t).add(aid);}
    void removerAluno(Usuario u,int tid,int aid){Map<String,Object> t=minhaTurma(u,tid);exigir(contem(t,aid),"Aluno não está nesta turma.");membros(t).removeIf(x->((Number)x).intValue()==aid);}
    String criarPasse(Usuario u,int tid,String nome,String matricula,String nascimento){minhaTurma(u,tid);String n=texto(nome,120);String mat=matricula.trim();exigir(mat.matches("[0-9]{1,20}"),"Matrícula deve conter de 1 a 20 dígitos.");LocalDate d=LocalDate.parse(nascimento);exigir(d.getYear()>=1900&&!d.isAfter(LocalDate.now()),"Data de nascimento inválida.");String prefix=d.format(DateTimeFormatter.ofPattern("ddMMyyyy"))+"-"+mat+"-";exigir(passes.stream().noneMatch(p->str(p,"codigo").startsWith(prefix))&&s.getUsuarios().stream().noneMatch(a->a.codigo().equalsIgnoreCase(prefix.substring(0,prefix.length()-1))||a.codigo().startsWith(prefix)),"Já existe um passe ou conta para esta matrícula e data. Vincule a conta existente ou cancele o passe pendente.");String codigo=prefix+Credenciais.codigo().substring(3,11);while(s.codigosInternos().contains(codigo))codigo=prefix+Credenciais.codigo().substring(3,11);passes.add(Json.obj("id",novoId(passes),"turma",tid,"nome",n,"codigo",codigo));s.codigosInternos().add(codigo);return codigo;}
    void cancelarPasse(Usuario u,int pid){Map<String,Object> p=achar(passes,pid);minhaTurma(u,id(p,"turma"));s.codigosInternos().remove(str(p,"codigo"));passes.remove(p);}
    void vincularCadastro(Usuario u,String codigo){for(Map<String,Object> p:new ArrayList<>(passes))if(str(p,"codigo").equals(codigo)){Map<String,Object> t=turma(id(p,"turma"));if(!contem(t,u.getId()))membros(t).add(u.getId());passes.remove(p);}}
    void publicar(Usuario u,int tid,String titulo,String descricao,String link,String arquivo,String base64){minhaTurma(u,tid);String title=texto(titulo,200);String desc=descricao.trim();exigir(desc.length()<=4000,"Descrição longa demais.");link=link.trim();arquivo=arquivo.trim();exigir(!link.isEmpty()||!base64.isEmpty(),"Anexe um PDF ou informe um link.");if(!link.isEmpty()){URI uri;try{uri=URI.create(link);}catch(Exception e){throw new IllegalArgumentException("Link inválido.");}exigir(link.length()<=2000&&("https".equalsIgnoreCase(uri.getScheme())||"http".equalsIgnoreCase(uri.getScheme()))&&uri.getHost()!=null&&uri.getUserInfo()==null,"Use um link HTTP ou HTTPS válido.");}int tamanho=0;if(!base64.isEmpty()){exigir(arquivo.length()>0&&arquivo.length()<=180&&arquivo.toLowerCase(Locale.ROOT).endsWith(".pdf"),"Anexe um arquivo PDF.");exigir(base64.length()<=((MAX_FILE+2)/3)*4,"PDF de até 2 MB.");byte[] bytes;try{bytes=Base64.getDecoder().decode(base64);}catch(Exception e){throw new IllegalArgumentException("Arquivo inválido.");}tamanho=bytes.length;exigir(tamanho>=5&&tamanho<=MAX_FILE&&bytes[0]==37&&bytes[1]==80&&bytes[2]==68&&bytes[3]==70&&bytes[4]==45,"PDF inválido ou maior que 2 MB.");long total=materiais.stream().mapToLong(m->id(m,"tamanho")).sum();exigir(total+tamanho<=MAX_TOTAL,"Limite de 16 MB de PDFs do piloto atingido. Use um link ou exclua materiais antigos.");}else arquivo="";materiais.add(Json.obj("id",novoId(materiais),"turma",tid,"titulo",title,"descricao",desc,"link",link,"arquivo",arquivo,"base64",base64,"tamanho",tamanho,"data",LocalDate.now().toString()));}
    void excluirMaterial(Usuario u,int mid){Map<String,Object> m=achar(materiais,mid);minhaTurma(u,id(m,"turma"));materiais.remove(m);}
    byte[] baixar(Usuario u,int mid){Map<String,Object> m=achar(materiais,mid);exigir(podeVer(u,id(m,"turma"))&&!str(m,"base64").isEmpty(),"Material indisponível para esta conta.");return Base64.getDecoder().decode(str(m,"base64"));}
    private Map<String,Object> resumo(Usuario u){return Json.obj("id",u.getId(),"nome",u.getNome());}
    Map<String,Object> estado(Usuario u){List<Object> ms=new ArrayList<>(),ts=new ArrayList<>(),ps=new ArrayList<>();Set<Integer> mids=new HashSet<>();for(Map<String,Object> t:turmas){int tid=id(t,"id");if(!podeVer(u,tid))continue;int mid=id(t,"materia");mids.add(mid);List<Object> alunos=new ArrayList<>(),pendentes=new ArrayList<>();if(u.isProfessor()){for(Object a:membros(t))alunos.add(resumo(s.usuario(((Number)a).intValue())));for(Map<String,Object> p:passes)if(id(p,"turma")==tid)pendentes.add(Json.obj("id",id(p,"id"),"nome",str(p,"nome")));}ts.add(Json.obj("id",tid,"nome",str(t,"nome"),"materia",mid,"materiaNome",str(materia(mid),"nome"),"professor",resumo(s.usuario(id(t,"professor"))),"membros",alunos,"pendentes",pendentes));}for(Map<String,Object> m:materias)if(u.isProfessor()?id(m,"professor")==u.getId():mids.contains(id(m,"id")))ms.add(Json.obj("id",id(m,"id"),"nome",str(m,"nome"),"professor",resumo(s.usuario(id(m,"professor")))));for(Map<String,Object> m:materiais)if(podeVer(u,id(m,"turma"))){Map<String,Object> c=new LinkedHashMap<>(m);c.remove("base64");c.put("turmaNome",nomeTurma(id(m,"turma")));c.put("materiaNome",str(materia(id(turma(id(m,"turma")),"materia")),"nome"));ps.add(c);}return Json.obj("materias",ms,"turmas",ts,"materiais",ps);}
    Map<String,Object> salvar(){return Json.obj("materias",materias,"turmas",turmas,"passes",passes,"materiais",materiais);}
    void carregar(Object raw){if(raw==null)return;Map<String,Object> m=Json.map(raw);for(String k:List.of("materias","turmas","passes","materiais")){List<Map<String,Object>> dest=k.equals("materias")?materias:k.equals("turmas")?turmas:k.equals("passes")?passes:materiais;for(Object x:Json.list(m.getOrDefault(k,List.of())))dest.add(Json.map(x));}}
}
